namespace sv_8933a8fe0e244b0bbea8e8d773511d3c.Services;

public class WarehouseInfo
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
}

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single user circuit.
/// Components subscribe to OnChange to react when the selection changes.
/// </summary>
public class WarehouseState
{
    public static readonly IReadOnlyList<WarehouseInfo> AvailableWarehouses =
    [
        new() { Id = "wh-a", Name = "Warehouse A" },
        new() { Id = "wh-b", Name = "Warehouse B" },
        new() { Id = "wh-c", Name = "Warehouse C" },
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;
    public string CurrentWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name ?? "Unknown";

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_8933a8fe0e244b0bbea8e8d773511d3c.Services;

/// <summary>
/// Scoped service that manages low-stock alert polling for the current user circuit.
/// Polls every 10 seconds when active and notifies all subscribers when new data arrives.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int LowStockCount { get; private set; }

    /// <summary>
    /// Fired when new alert data arrives. Subscribers must wrap StateHasChanged
    /// in InvokeAsync since this fires from a timer thread.
    /// </summary>
    public event Action? OnAlertDataChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning low-stock item count.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component that needs polling becomes active.
    /// Starts the timer on the first subscriber.
    /// </summary>
    public async Task StartPollingAsync()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            await FetchAndNotifyAsync();
            StartTimer();
        }
    }

    /// <summary>
    /// Call when a component that needs polling is disposed.
    /// Stops the timer when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            StopTimer();
        }
    }

    private void StartTimer()
    {
        StopTimer();
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private void StopTimer()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (_timer is not null && await _timer.WaitForNextTickAsync(ct))
            {
                await FetchAndNotifyAsync();
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task FetchAndNotifyAsync()
    {
        LowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        OnAlertDataChanged?.Invoke();
    }

    private async void OnWarehouseChanged()
    {
        if (_subscriberCount > 0)
        {
            await FetchAndNotifyAsync();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        StopTimer();
    }
}

