@using sv_8933a8fe0e244b0bbea8e8d773511d3c.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard - @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-4" style="max-width: 500px;">
    <div class="card-header">
        <strong>@WarehouseState.CurrentWarehouseName</strong> — Inventory Alerts
    </div>
    <div class="card-body">
        <p class="card-text fs-4">
            Low-stock items:
            <span class="badge @(AlertService.LowStockCount > 0 ? "bg-danger" : "bg-success") fs-5">
                @AlertService.LowStockCount
            </span>
        </p>
        <p class="text-muted">
            Auto-refreshes every 10 seconds. Switch warehouses in the top bar to see alerts for a different site.
        </p>
    </div>
    <div class="card-footer text-muted">
        Polling active for <code>@WarehouseState.CurrentWarehouseId</code>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override async Task OnInitializedAsync()
    {
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        _alertHandler = () => InvokeAsync(StateHasChanged);

        WarehouseState.OnChange += _warehouseHandler;
        AlertService.OnAlertDataChanged += _alertHandler;

        // Start polling when this page becomes visible
        await AlertService.StartPollingAsync();
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.OnAlertDataChanged -= _alertHandler;

        // Stop polling when user leaves the page
        AlertService.StopPolling();
    }
}

